package com.sunrise.dentalclinic.service;
import com.sunrise.dentalclinic.dto.SummaryResponse; import com.sunrise.dentalclinic.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*;
@Service public class DashboardService {private final AppointmentRepository a;private final PatientRepository p;private final DentistRepository d;private final BillRepository b; public DashboardService(AppointmentRepository a,PatientRepository p,DentistRepository d,BillRepository b){this.a=a;this.p=p;this.d=d;this.b=b;}
 @Transactional(readOnly=true) public SummaryResponse summary(){var today=LocalDate.now(ZoneId.of("Asia/Colombo"));return new SummaryResponse(a.findByAppointmentDateOrderByAppointmentTime(today).size(),a.findByAppointmentDateGreaterThanEqualOrderByAppointmentDateAscAppointmentTimeAsc(today.plusDays(1)).size(),p.count(),d.count(),b.revenue(today.atStartOfDay(),today.plusDays(1).atStartOfDay()));}}
